"""Offline boundary tests; generated byte fixtures are not CIFAR evidence."""
import gzip,hashlib,io,json,tarfile,tempfile,unittest
from pathlib import Path
from unittest.mock import patch
import public_assets as assets

class AssetsTests(unittest.TestCase):
    def directory(self):
        folder=tempfile.TemporaryDirectory();self.addCleanup(folder.cleanup);return Path(folder.name)
    def test_fixed_spec_and_missing_approval_precede_network_or_writes(self):
        spec=assets.specification();self.assertEqual(len(spec['assets']),5)
        self.assertEqual(spec['redirects'],0);self.assertEqual(spec['retries'],0)
        recovery=assets.recovery_specification()
        self.assertNotEqual(spec['binding'],recovery['binding'])
        self.assertEqual({a['url']for a in spec['assets']},{a['url']for a in recovery['assets']})
        self.assertEqual(recovery['assets'][-1]['id'],'cifar10-binary')
        self.assertEqual(recovery['assets'][-1]['max_seconds'],600)
        self.assertFalse(recovery['automatically_authorized'])
        out=self.directory()/'out'
        with patch('http.client.HTTPSConnection',side_effect=AssertionError('network forbidden')):
            for receipt in (None,{},dict(format='poseidon-explicit-public-asset-approval-v1',status='approved',proposal_binding='0'*64),dict(format='poseidon-explicit-public-asset-approval-v1',status='approved',proposal_binding=recovery['binding'],allowed_urls=[a['url']for a in recovery['assets']])):
                with self.assertRaisesRegex(ValueError,'explicit matching approval'):assets.download_assets(spec,out,receipt,checkpoint=lambda:None)
        self.assertFalse(out.exists())
    def test_exact_multi_file_stream_and_caps(self):
        root=self.directory();raw=b'original bytes\x00\xff'*600000
        value=assets.store_stream(io.BytesIO(raw),root/'chunks',len(raw),checkpoint=lambda:None)
        self.assertGreater(len(value['parts']),1)
        self.assertTrue(all(p['bytes']<=8*1024**2 for p in value['parts']))
        reader=assets.ChunkReader(root/'chunks',value)
        collected=bytearray()
        while True:
            part=reader.read(65536)
            if not part:break
            collected.extend(part)
        self.assertEqual(bytes(collected),raw)
        with self.assertRaisesRegex(ValueError,'byte budget'):assets.store_stream(io.BytesIO(b'abcd'),root/'over',3,checkpoint=lambda:None)
        with self.assertRaisesRegex(ValueError,'checksum mismatch'):assets.store_stream(io.BytesIO(b'abcd'),root/'hash',4,expected_md5='0'*32,checkpoint=lambda:None)
    def test_changed_chunk_and_indirect_file_rejected(self):
        root=self.directory();value=assets.store_stream(io.BytesIO(b'abcd'),root/'data',4,checkpoint=lambda:None)
        p=root/'data'/value['parts'][0]['name'];p.write_bytes(b'abce')
        with self.assertRaisesRegex(ValueError,'Chunk digest'):assets.ChunkReader(root/'data',value)
        p.unlink();p.symlink_to(root/'nonexistent')
        with self.assertRaisesRegex(ValueError,'Indirect chunk'):assets.ChunkReader(root/'data',value)
    def archive(self,members):
        output=io.BytesIO()
        with tarfile.open(fileobj=output,mode='w:gz',compresslevel=1)as archive:
            for name,value,kind in members:
                item=tarfile.TarInfo(name);item.type=kind;item.size=len(value)if kind==tarfile.REGTYPE else 0
                if kind==tarfile.SYMTYPE:item.linkname='/private/file'
                archive.addfile(item,io.BytesIO(value)if kind==tarfile.REGTYPE else None)
        return output.getvalue()
    def prepare_fixture(self,raw):
        root=self.directory();manifest=assets.store_stream(io.BytesIO(raw),root/'raw',192*1024**2,checkpoint=lambda:None)
        return root,manifest
    def test_exact_official_sized_records_stream_losslessly(self):
        row_group=b''.join(bytes([i])+bytes([i])*3072 for i in range(10))
        raw_batch=row_group*1000
        members=[('cifar-10-batches-bin/data_batch_%d.bin'%i,raw_batch,tarfile.REGTYPE)for i in range(1,6)]
        members += [('cifar-10-batches-bin/test_batch.bin',raw_batch,tarfile.REGTYPE),('cifar-10-batches-bin/batches.meta.txt',b'fixture labels\n',tarfile.REGTYPE)]
        root,manifest=self.prepare_fixture(self.archive(members))
        # Only this generated offline fixture substitutes its checksum. No real asset is fetched or treated as official data.
        with patch.object(assets,'CIFAR_MD5',manifest['md5']):
            result=assets.prepare_binary_records(root/'raw',manifest,root/'records',checkpoint=lambda:None)
        self.assertEqual(result['train_count'],50000);self.assertEqual(result['test_count'],10000)
        self.assertEqual(len(result['shards']),60)
        for shard in result['shards']:
            value=(root/'records'/shard['file']).read_bytes()
            self.assertEqual(value,raw_batch[:1000*3073]);self.assertLess(len(value),assets.CHUNK)
    def test_archive_member_path_type_size_and_checksum_rejection(self):
        cases=[('../private',b'x',tarfile.REGTYPE),('cifar-10-batches-bin/link',b'',tarfile.SYMTYPE),('cifar-10-batches-bin/data_batch_1.bin',b'x',tarfile.REGTYPE)]
        for member in cases:
            root,manifest=self.prepare_fixture(self.archive([member]))
            with patch.object(assets,'CIFAR_MD5',manifest['md5']),self.assertRaises(ValueError):assets.prepare_binary_records(root/'raw',manifest,root/'records',checkpoint=lambda:None)
        bad=bytes([255])+bytes(10000*3073-1)
        for members in ([('cifar-10-batches-bin/data_batch_1.bin',bad,tarfile.REGTYPE)],[('cifar-10-batches-bin/batches.meta.txt',b'one',tarfile.REGTYPE),('cifar-10-batches-bin/batches.meta.txt',b'two',tarfile.REGTYPE)]):
            root,manifest=self.prepare_fixture(self.archive(members))
            with patch.object(assets,'CIFAR_MD5',manifest['md5']),self.assertRaises(ValueError):assets.prepare_binary_records(root/'raw',manifest,root/'records',checkpoint=lambda:None)
        root,manifest=self.prepare_fixture(b'untrusted')
        with self.assertRaisesRegex(ValueError,'approved official'):assets.prepare_binary_records(root/'raw',manifest,root/'records',checkpoint=lambda:None)
    def test_http_redirect_is_terminal_and_request_has_no_credentials(self):
        spec=assets.specification();approval=dict(format='poseidon-explicit-public-asset-approval-v1',status='approved',proposal_binding=spec['binding'],allowed_urls=[a['url']for a in spec['assets']])
        events=[]
        class Connection:
            def __init__(self,*args,**kwargs):events.append(('connection',args));self.sock=None
            def request(self,*args,**kwargs):events.append(('request',args,kwargs))
            def getresponse(self):return type('Response',(),dict(status=302))()
            def close(self):events.append(('close',))
        with patch('http.client.HTTPSConnection',Connection),self.assertRaisesRegex(ValueError,'HTTP status'):
            assets.download_assets(spec,self.directory()/'download',approval,checkpoint=lambda:None)
        sent=[e for e in events if e[0]=='request'];self.assertEqual(len(sent),1)
        self.assertEqual(sent[0][1],('GET','/kriz/cifar-10-binary.tar.gz'))
        self.assertNotIn('Authorization',sent[0][2]['headers'])
    def test_interrupted_sub_chunk_and_checkpoint_preserve_returned_bytes(self):
        root=self.directory();raw=b'partial original bytes\x00\xff'*200
        class Interrupted:
            calls=0
            def read(self,size):
                self.calls+=1
                if self.calls==1:return raw
                raise TimeoutError('fixture interrupted read')
        with self.assertRaises(TimeoutError):assets.store_stream(Interrupted(),root/'interrupted',assets.CHUNK,checkpoint=lambda:None)
        manifest=json.loads((root/'interrupted/incomplete-stream.json').read_text())
        self.assertFalse(manifest['complete']);self.assertEqual(manifest['bytes_returned_by_stream'],len(raw))
        self.assertEqual(b''.join((root/'interrupted'/part['name']).read_bytes()for part in manifest['parts']),raw)
        self.assertFalse((root/'interrupted/stream.json').exists())
        with self.assertRaisesRegex(ValueError,'Chunk manifest'):assets.ChunkReader(root/'interrupted',manifest)
        block=b'x'*assets.CHUNK
        def stop():raise RuntimeError('fixture checkpoint stop')
        with self.assertRaisesRegex(RuntimeError,'checkpoint stop'):assets.store_stream(io.BytesIO(block),root/'checkpoint',assets.CHUNK,checkpoint=stop)
        retained=json.loads((root/'checkpoint/incomplete-stream.json').read_text())
        self.assertEqual(retained['bytes_returned_by_stream'],len(block))
        self.assertEqual(sum(part['bytes']for part in retained['parts']),len(block))
        self.assertFalse((root/'checkpoint/stream.json').exists())
    def test_empty_stream_and_unbounded_read_rejected(self):
        root=self.directory()
        with self.assertRaisesRegex(ValueError,'Empty'):assets.store_stream(io.BytesIO(b''),root/'empty',4,checkpoint=lambda:None)
        value=assets.store_stream(io.BytesIO(b'abcd'),root/'data',4,checkpoint=lambda:None)
        with self.assertRaisesRegex(ValueError,'Bounded chunk read'):assets.ChunkReader(root/'data',value).read()
if __name__=='__main__':unittest.main()
